//! Build-time codegen for `equipment.json`: one static row per wearable,
//! sorted by debugname (the dump object already iterates sorted) for
//! `binary_search` in `by_name`.

/// Render `equipment_generated.rs` from the parsed dump.
pub fn generate(manifest_dir: &str) {
    let parsed = crate::parse_dump(manifest_dir, "equipment");
    let fields = match &parsed {
        crate::workspace_json::Value::Obj(fields) => fields,
        _ => panic!("equipment dump must be a JSON object of rows"),
    };
    let mut generated = String::from(
        "// Generated by rs/crates/gamedata/build.rs from gamedata/data/equipment.json - do not edit.\n\
         pub static ALL: &[super::StaticWearable] = &[\n",
    );
    for (name, row) in fields {
        generated.push_str(&format!(
            "    super::StaticWearable {{ name: \"{}\", wearpos: {}, wearpos2: {}, wearpos3: {}, \
             category: {}, attack: {}, defence: {}, strength: {}, prayer: {}, requirements: {}, \
             quest: {}, tier: {}, rangebonus: {} }},\n",
            crate::escape_for_rust_literal(name),
            crate::int_or(row, "wearpos", -1),
            crate::int_or(row, "wearpos2", -1),
            crate::int_or(row, "wearpos3", -1),
            crate::render_opt_str(row.get("category")),
            crate::render_str_int_map(row, "attack"),
            crate::render_str_int_map(row, "defence"),
            crate::int_or(row, "strength", 0),
            crate::int_or(row, "prayer", 0),
            crate::render_str_int_map(row, "requirements"),
            crate::render_opt_str(row.get("quest")),
            crate::int_or(row, "tier", -1),
            crate::int_or(row, "rangebonus", -1),
        ));
    }
    generated.push_str("];\n");
    crate::emit_generated("equipment_generated.rs", &generated);
}
